INSERT INTO `masini` (`description`, `keywords`, `title`, `oferta_speciala`, `stare_anunt`, `id`, `cat`, `marca`, `tip`, `combustibil`, `an`, `detalii`, `pret`, `pret_vechi`, `prov_enienta`, `subcateg`, `pre_anunt`) VALUES
('rate, persoane fizice, leasing firma, intreprindere individuala, pfa', 'rate, persoane fizice, leasing firma, intreprindere individuala, pfa', 'AUTOLAND ROMANIA - dealer auto second hand, finantari in rate sau leasing, garantie auto si asistenta rutiera, acte complete - inclusiv inmatriculari!!!', 0, 1, 1159, 'Autoutilitare', 'Renault', 'MASTER L5H2 3500kg catB - roti duble', 'motorina', 2013, '<ul>\r\n	<li><font size=\"2\">Motor Turbo-DIESEL 2.3L DCi EURO5;</font></li>\r\n	<li><font size=\"2\">Putere motor: 92kW / 125CP;</font></li>\r\n	<li><font size=\"2\">Transmisie: fata;</font></li>\r\n	<li><font size=\"2\">Km. parcursi: 172 500;</font></li>\r\n	<li><font size=\"2\">Sarcina maxima autorizata: 3500kg;</font></li>\r\n	<li><font size=\"2\">Cutie de viteze manuala 6+1 trepte;</font></li>\r\n	<li><font size=\"2\">Sistem de directie servo-asistat;</font></li>\r\n	<li><font size=\"2\">Sistem de franare servo-asistat;</font></li>\r\n	<li><font size=\"2\">ABS si ESP;</font></li>\r\n	<li><font size=\"2\">Airbag sofer;</font></li>\r\n	<li><font size=\"2\">Geamuri electrice fata;</font></li>\r\n	<li><font size=\"2\">Oglinzi cu reglare electrica;</font></li>\r\n	<li><font size=\"2\">Radio-CD MP3 player, comenzi audio la volan;</font></li>\r\n	<li><font size=\"2\"><strong>Sistem de aer conditionat;</strong></font></li>\r\n	<li><font size=\"2\">Bancheta dubla pasager;</font></li>\r\n	<li><font size=\"2\">Scaun sofer cu reglare pe inaltime;</font></li>\r\n	<li><font size=\"2\">Imobilizator electronic motor;</font></li>\r\n	<li><font size=\"2\">Inchidere centralizata cu telecomanda;</font></li>\r\n	<li><font size=\"2\">Acoperis supra-inaltat;</font></li>\r\n	<li><font size=\"2\">Perete despartitor compartiment marfa;</font></li>\r\n	<li><font size=\"2\">Lungime utila: 4,40m;</font></li>\r\n	<li><font size=\"2\">Usa culisanta lateral dreapta, u</font><span style=\"font-size: small\">si duble spate;</span></li>\r\n	<li><span style=\"font-size: small\">Roti duble spate;</span></li>\r\n	<li><strong><font size=\"2\">Verificare tehnica efectuata;</font></strong></li>\r\n	<li><font size=\"2\">Posibilitate de achizitie: leasing, rate, cash.</font></li>\r\n</ul>\r\n', 14500, 0, 'Import', 'Utilitare Mari', 'GARANTIE 6 LUNI; POSIBILITATE FINANTARE MAX. 5 ANI SI ASISTENTA RUTIERA'),
